import { isPrimitive } from "./isPrimitive";
export const isArraysEqualShallow = (arr1, arr2) => {
    if (arr1.length !== arr2.length) {
        return false;
    }
    for (let i = 0; i < arr1.length; i++) {
        if (!isPrimitive(arr1[i]) || !isPrimitive(arr2[i])) {
            return false;
        }
        if (arr1[i] !== arr2[i]) {
            return false;
        }
    }
    return true;
};
